sp_widget.client_script:
api.controller = function($scope,$timeout,$location,nowAttachmentHandler) {
  var c = this;

  c.filters = {};
  c.loading = false;
  c.refreshing = false;
  c.uploading = false;
  c.submitting = false;
  c.sortDescending = true;

  c.showCompletionForm = false;
  c.attachmentButtonVisible = false;

  c.successMessage = "";
  c.errorMessage = "";
  c.formError = "";
  c.uploadMessage = "";

  c.selectedRecord = {};
  c.completionForm = {};
  c.attachments = [];

  /*
   * Request number autocomplete variables.
   */
  c.requestSearch = "";
  c.showRequestDropdown = false;
  c.filteredRequestNumbers = [];
  c.activeRequestIndex = -1;

  c.displayRecords = angular.copy(
    c.data.records || []
  );

  $scope.attachmentHandler = null;

  initializeRequestNumbers();

  function initializeRequestNumbers() {
    var requestNumbers = [];

    if (
      c.data.filterOptions &&
      c.data.filterOptions.requestNumbers
    ) {
      requestNumbers =
        c.data.filterOptions.requestNumbers;
    }

    c.filteredRequestNumbers =
      angular.copy(requestNumbers);
  }

  function updateDisplayRecords(records) {
    var updatedRecords = records || [];

    c.data.records = updatedRecords;
    c.displayRecords = updatedRecords.slice(0);

    if (!c.sortDescending) {
      c.displayRecords.reverse();
    }
  }

  /*
   * Request number autocomplete.
   */
  c.filterRequestNumbers = function() {
    var searchValue = String(
      c.requestSearch || ""
    ).trim().toLowerCase();

    var requestNumbers =
      c.data.filterOptions &&
      c.data.filterOptions.requestNumbers
        ? c.data.filterOptions.requestNumbers
        : [];

    c.filters.requestNumber =
      String(c.requestSearch || "").trim();

    if (!searchValue) {
      c.filteredRequestNumbers =
        angular.copy(requestNumbers);
    } else {
      c.filteredRequestNumbers =
        requestNumbers.filter(function(number) {
          return String(number)
            .toLowerCase()
            .indexOf(searchValue) !== -1;
        });
    }

    c.activeRequestIndex = -1;
    c.showRequestDropdown = true;
  };

  c.openRequestDropdown = function() {
    c.filterRequestNumbers();
    c.showRequestDropdown = true;
  };

  c.toggleRequestDropdown = function(event) {
    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }

    c.showRequestDropdown =
      !c.showRequestDropdown;

    if (c.showRequestDropdown) {
      c.filterRequestNumbers();
    }
  };

  c.hideRequestDropdown = function() {
    $timeout(function() {
      c.showRequestDropdown = false;
      c.activeRequestIndex = -1;
    }, 200);
  };

  c.selectRequestNumber = function(
    requestNumber,
    event
  ) {
    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }

    c.requestSearch = requestNumber || "";
    c.filters.requestNumber =
      requestNumber || "";

    c.showRequestDropdown = false;
    c.activeRequestIndex = -1;
  };

  c.clearRequestNumber = function(event) {
    if (event) {
      event.preventDefault();
      event.stopPropagation();
    }

    c.requestSearch = "";
    c.filters.requestNumber = "";
    c.activeRequestIndex = -1;

    initializeRequestNumbers();

    c.showRequestDropdown = true;
  };

  c.handleRequestKeydown = function(event) {
    if (!event) {
      return;
    }

    var keyCode = event.which || event.keyCode;
    var options =
      c.filteredRequestNumbers || [];

    /*
     * Down arrow.
     */
    if (keyCode === 40) {
      event.preventDefault();

      c.showRequestDropdown = true;

      if (!options.length) {
        return;
      }

      c.activeRequestIndex++;

      if (
        c.activeRequestIndex >= options.length
      ) {
        c.activeRequestIndex = 0;
      }

      return;
    }

    /*
     * Up arrow.
     */
    if (keyCode === 38) {
      event.preventDefault();

      if (!options.length) {
        return;
      }

      c.activeRequestIndex--;

      if (c.activeRequestIndex < 0) {
        c.activeRequestIndex =
          options.length - 1;
      }

      return;
    }

    /*
     * Enter.
     */
    if (keyCode === 13) {
      event.preventDefault();

      if (
        c.showRequestDropdown &&
        c.activeRequestIndex >= 0 &&
        options[c.activeRequestIndex]
      ) {
        c.selectRequestNumber(
          options[c.activeRequestIndex]
        );
      }

      c.search();
      return;
    }

    /*
     * Escape.
     */
    if (keyCode === 27) {
      c.showRequestDropdown = false;
      c.activeRequestIndex = -1;
    }
  };

  c.openView = function(record) {
    if (!record || !record.sys_id) {
      return;
    }

    $location.url(
      "?id=view_record_asean&sys_id=" +
      encodeURIComponent(record.sys_id)
    );
  };

  c.openEdit = function(record) {
    if (!record || !record.sys_id) {
      return;
    }

    if (record.statusValue !== "draft") {
      c.errorMessage =
        "Only Draft applications can be edited.";
      return;
    }

    $location.url(
      "?id=edit_registration_asean&sys_id=" +
      encodeURIComponent(record.sys_id)
    );
  };

  c.openFeedback = function(record) {
    if (!record || !record.sys_id) {
      return;
    }

    if (
      record.statusValue !== "pending_feedback"
    ) {
      c.errorMessage =
        "Feedback is available only for " +
        "Pending Feedback applications.";
      return;
    }

    $location.url(
      "?id=feedback_asean&sys_id=" +
      encodeURIComponent(record.sys_id)
    );
  };

  c.goBack = function() {
    $location.url("?id=employee_role_asean");
  };

  c.search = function() {
    if (c.loading || c.refreshing) {
      return;
    }

    /*
     * Use typed text even when user does not
     * select an item from the dropdown.
     */
    c.filters.requestNumber = String(
      c.requestSearch || ""
    ).trim();

    c.showRequestDropdown = false;
    c.loading = true;
    c.errorMessage = "";

    c.server.get({
      action: "search",
      filters: angular.copy(c.filters)
    }).then(
      function(response) {
        updateDisplayRecords(
          response.data.records || []
        );

        if (
          response.data.success === false &&
          response.data.message
        ) {
          c.errorMessage =
            response.data.message;
        }

        c.loading = false;
      },
      function() {
        c.loading = false;
        c.errorMessage =
          "Unable to search the learning applications.";
      }
    );
  };

  c.reset = function() {
    if (c.loading || c.refreshing) {
      return;
    }

    c.filters = {};
    c.requestSearch = "";
    c.showRequestDropdown = false;
    c.activeRequestIndex = -1;

    c.sortDescending = true;
    c.loading = true;
    c.errorMessage = "";

    c.server.get({
      action: "reset",
      filters: {}
    }).then(
      function(response) {
        updateDisplayRecords(
          response.data.records || []
        );

        if (response.data.filterOptions) {
          c.data.filterOptions =
            response.data.filterOptions;
        }

        initializeRequestNumbers();

        c.loading = false;
      },
      function() {
        c.loading = false;
        c.errorMessage =
          "Unable to reset the learning applications.";
      }
    );
  };

  c.refresh = function() {
    if (c.refreshing || c.loading) {
      return;
    }

    c.filters.requestNumber = String(
      c.requestSearch || ""
    ).trim();

    c.showRequestDropdown = false;
    c.refreshing = true;
    c.errorMessage = "";

    var refreshTimeout = $timeout(
      function() {
        if (c.refreshing) {
          c.refreshing = false;
          c.errorMessage =
            "Refresh took too long. Please try again.";
        }
      },
      15000
    );

    c.server.get({
      action: "refresh",
      filters: angular.copy(c.filters)
    }).then(
      function(response) {
        $timeout.cancel(refreshTimeout);

        updateDisplayRecords(
          response.data.records || []
        );

        if (response.data.filterOptions) {
          c.data.filterOptions =
            response.data.filterOptions;

          initializeRequestNumbers();
        }

        c.refreshing = false;
      },
      function() {
        $timeout.cancel(refreshTimeout);

        c.refreshing = false;
        c.errorMessage =
          "Unable to refresh the learning applications.";
      }
    );
  };

  c.toggleSort = function() {
    if (c.loading || c.refreshing) {
      return;
    }

    c.sortDescending = !c.sortDescending;
    c.displayRecords.reverse();
  };

  c.getStatusClass = function(statusValue) {
    switch (statusValue) {
      case "draft":
        return "status-draft";

      case "submitted":
        return "status-submitted";

      case "pending_manager_approval":
      case "pending_l2_approval":
      case "pending_hr_review":
        return "status-approval";

      case "approved":
        return "status-approved";

      case "learning_in_progress":
        return "status-progress";

      case "pending_feedback":
        return "status-feedback";

      case "completed":
        return "status-complete";

      case "rejected":
        return "status-rejected";

      default:
        return "status-default";
    }
  };

  c.openCompletionForm = function(record) {
    if (!record || !record.sys_id) {
      return;
    }

    if (
      record.statusValue !==
      "learning_in_progress"
    ) {
      c.errorMessage =
        "Certificate upload is available only for " +
        "Learning In Progress applications.";
      return;
    }

    c.formError = "";
    c.uploadMessage = "";
    c.successMessage = "";
    c.errorMessage = "";
    c.attachments = [];
    c.attachmentButtonVisible = false;

    c.selectedRecord =
      angular.copy(record);

    c.completionForm = {
      requestNumber:
        record.requestNumber || "",
      employeeName:
        record.employeeName || "",
      courseTitle:
        record.courseTitle || "",
      courseStartDate:
        record.courseStartDate || "",
      courseEndDate:
        record.courseEndDate || "",
      completionComment: ""
    };

    initializeAttachmentHandler(
      record.sys_id
    );

    c.showCompletionForm = true;

    $timeout(function() {
      c.attachmentButtonVisible = true;
      c.loadAttachments();
    }, 100);
  };

  function initializeAttachmentHandler(sysId) {
    function attachmentSuccess(
      attachments,
      action
    ) {
      c.uploading = false;
      c.attachments = attachments || [];

      if (action === "added") {
        c.uploadMessage =
          "Certificate uploaded successfully.";
      }

      if (action === "deleted") {
        c.uploadMessage =
          "Certificate removed successfully.";
      }

      c.loadAttachments();
      $scope.$evalAsync();
    }

    function attachmentError(error) {
      c.uploading = false;

      if (error && error.msg) {
        c.formError =
          error.msg +
          (
            error.fileName
              ? " " + error.fileName
              : ""
          );
      } else {
        c.formError =
          "Certificate upload failed.";
      }

      $scope.$evalAsync();
    }

    $scope.attachmentHandler =
      new nowAttachmentHandler(
        attachmentSuccess,
        attachmentError
      );

    $scope.attachmentHandler.setParams(
      "x_1549902_asean_0_learning_application",
      sysId,
      10 * 1024 * 1024
    );
  }

  $scope.$on(
    "dialog.upload_too_large.show",
    function() {
      c.uploading = false;
      c.formError =
        "The certificate exceeds the maximum " +
        "allowed size of 10 MB.";

      $scope.$evalAsync();
    }
  );

  $scope.$on(
    "attachment.upload.start",
    function() {
      c.uploading = true;
      c.formError = "";
      c.uploadMessage = "";

      $scope.$evalAsync();
    }
  );

  $scope.$on(
    "sp.attachments.update",
    function() {
      c.uploading = false;

      if (
        c.showCompletionForm &&
        c.selectedRecord &&
        c.selectedRecord.sys_id
      ) {
        c.loadAttachments();
      }
    }
  );

  c.loadAttachments = function() {
    if (
      !c.showCompletionForm ||
      !c.selectedRecord ||
      !c.selectedRecord.sys_id
    ) {
      return;
    }

    c.server.get({
      action: "get_attachments",
      sys_id: c.selectedRecord.sys_id
    }).then(
      function(response) {
        c.attachments =
          response.data.attachments || [];

        c.uploading = false;

        if (
          response.data.success === false &&
          response.data.message
        ) {
          c.formError =
            response.data.message;
        }
      },
      function() {
        c.uploading = false;
        c.formError =
          "Unable to load uploaded certificates.";
      }
    );
  };

  c.deleteAttachment = function(
    attachment
  ) {
    if (
      !$scope.attachmentHandler ||
      !attachment
    ) {
      return;
    }

    c.formError = "";
    c.uploadMessage = "";

    $scope.attachmentHandler
      .deleteAttachment(attachment);
  };

  c.submitForFeedback = function() {
    if (c.submitting || c.uploading) {
      return;
    }

    c.formError = "";
    c.uploadMessage = "";

    var completionComment =
      c.completionForm.completionComment
        ? String(
            c.completionForm.completionComment
          ).trim()
        : "";

    if (!completionComment) {
      c.formError =
        "Completion Comments are mandatory.";
      return;
    }

    if (
      !c.attachments ||
      c.attachments.length === 0
    ) {
      c.formError =
        "Please upload the completion certificate.";
      return;
    }

    c.submitting = true;

    c.server.get({
      action: "submit_for_feedback",
      sys_id: c.selectedRecord.sys_id,

      form: {
        requestNumber:
          c.completionForm.requestNumber,

        employeeName:
          c.completionForm.employeeName,

        courseTitle:
          c.completionForm.courseTitle,

        courseStartDate:
          c.completionForm.courseStartDate,

        courseEndDate:
          c.completionForm.courseEndDate,

        completionComment:
          completionComment
      },

      filters: angular.copy(c.filters)
    }).then(
      function(response) {
        c.submitting = false;

        if (response.data.success) {
          c.attachmentButtonVisible = false;
          $scope.attachmentHandler = null;
          c.attachments = [];

          c.successMessage =
            response.data.message ||
            "Certificate and comments submitted successfully.";

          updateDisplayRecords(
            response.data.records || []
          );

          $timeout(function() {
            c.showCompletionForm = false;
            c.selectedRecord = {};
            c.completionForm = {};
          }, 50);

          $timeout(function() {
            c.successMessage = "";
          }, 7000);
        } else {
          c.formError =
            response.data.message ||
            "Unable to update the learning application.";
        }
      },
      function() {
        c.submitting = false;
        c.formError =
          "An unexpected error occurred while submitting.";
      }
    );
  };

  c.overlayClick = function(event) {
    if (
      event &&
      event.target !== event.currentTarget
    ) {
      return;
    }

    c.closeCompletionForm();
  };

  c.closeCompletionForm = function() {
    if (c.submitting || c.uploading) {
      return;
    }

    c.attachmentButtonVisible = false;
    $scope.attachmentHandler = null;
    c.attachments = [];
    c.formError = "";
    c.uploadMessage = "";

    $timeout(function() {
      c.showCompletionForm = false;
      c.selectedRecord = {};
      c.completionForm = {};
    }, 50);
  };
};

sp_widget.css:
.learning-records-page {
  position: relative;
  width: 100%;
  min-height: 610px;
  overflow: visible;
  background: #ffffff;
  border: 1px solid #555555;
  font-family: Arial, Helvetica, sans-serif;
}

.records-page-header {
  display: flex;
  min-height: 84px;
  padding: 12px 20px;
  align-items: flex-start;
  background: #ffffff;
  border-bottom: 1px solid #dddddd;
}

.records-title {
  flex: 1;
  color: #ed6b21;
  font-size: 28px;
  font-weight: 500;
  line-height: 55px;
}

.logged-in-user-details {
  width: 390px;
  padding-top: 4px;
  margin-right: 20px;
}

.user-detail-row {
  display: flex;
  margin-bottom: 8px;
  align-items: center;
}

.user-detail-label {
  width: 95px;
  color: #666666;
  font-size: 12px;
}

.user-detail-value {
  color: #222222;
  font-size: 15px;
  text-decoration: underline;
}

.healthineers-logo {
  position: relative;
  min-width: 165px;
  padding-right: 30px;
  text-align: right;
}

.siemens-text {
  color: #009999;
  font-size: 20px;
  font-weight: 700;
  letter-spacing: 1px;
}

.healthineers-text {
  color: #ed6b21;
  font-size: 18px;
  font-weight: 700;
}

.healthineers-dots {
  position: absolute;
  top: 5px;
  right: 0;
  width: 23px;
}

.healthineers-dots span {
  display: block;
  width: 7px;
  height: 7px;
  margin: 2px auto;
  background: #ed6b21;
  border-radius: 50%;
}

.main-message {
  margin: 12px 18px;
}

.records-filter-section {
  position: relative;
  z-index: 30;
  padding: 18px 30px 20px;
  overflow: visible;
  background: #eeeeee;
  border-bottom: 1px solid #d4d4d4;
}

.filter-section-title {
  padding-bottom: 12px;
  margin-bottom: 15px;
  color: #444444;
  border-bottom: 1px solid #d2d2d2;
  font-size: 17px;
  font-weight: 600;
}

.filter-section-title i {
  margin-right: 7px;
  color: #ed6b21;
}

.filter-fields-container {
  display: grid;
  max-width: 1100px;
  margin: 0 auto;
  overflow: visible;
  grid-template-columns:
    repeat(2, minmax(320px, 1fr));
  column-gap: 40px;
  row-gap: 15px;
}

.filter-item {
  position: relative;
  display: flex;
  min-width: 0;
  overflow: visible;
  align-items: center;
}

.filter-item label {
  width: 160px;
  margin: 0 12px 0 0;
  color: #444444;
  font-size: 14px;
  font-weight: 600;
  text-align: right;
}

.filter-control {
  flex: 1;
  height: 38px;
  min-width: 0;
  padding: 5px 30px 5px 10px;
  color: #333333;
  background: #ffffff;
  border: 1px solid #bdbdbd;
  border-radius: 2px;
  box-shadow: none;
}

/*
 * Request number autocomplete.
 */
.request-filter-item {
  z-index: 50;
}

.request-filter-container {
  position: relative;
  flex: 1;
  min-width: 0;
  overflow: visible;
}

.request-input-wrapper {
  position: relative;
  width: 100%;
}

.request-number-input {
  width: 100%;
  padding-right: 64px;
}

.request-dropdown-button {
  position: absolute;
  top: 1px;
  right: 1px;
  width: 34px;
  height: 36px;
  padding: 0;
  color: #555555;
  background: transparent;
  border: 0;
  cursor: pointer;
}

.request-dropdown-button:hover {
  color: #ed6b21;
  background: #f7f7f7;
}

.request-clear-button {
  position: absolute;
  top: 1px;
  right: 35px;
  width: 28px;
  height: 36px;
  padding: 0;
  color: #888888;
  background: transparent;
  border: 0;
  cursor: pointer;
}

.request-clear-button:hover {
  color: #d9534f;
}

.request-dropdown {
  position: absolute;
  z-index: 9999;
  top: calc(100% + 2px);
  right: 0;
  left: 0;
  max-height: 230px;
  padding: 0;
  margin: 0;
  overflow-x: hidden;
  overflow-y: auto;
  background: #ffffff;
  border: 1px solid #aaaaaa;
  border-radius: 2px;
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.18);
  list-style: none;
}

.request-dropdown li {
  padding: 10px 12px;
  color: #333333;
  background: #ffffff;
  border-bottom: 1px solid #eeeeee;
  font-size: 13px;
  cursor: pointer;
}

.request-dropdown li:last-child {
  border-bottom: 0;
}

.request-dropdown li i {
  margin-right: 7px;
  color: #ed6b21;
}

.request-dropdown li:hover,
.request-dropdown .request-option-active {
  color: #222222;
  background: #fff2e9;
}

.request-dropdown .request-dropdown-all {
  color: #444444;
  font-weight: 600;
}

.request-dropdown .request-dropdown-empty {
  color: #777777;
  background: #fafafa;
  font-style: italic;
  text-align: center;
  cursor: default;
}

.request-dropdown .request-dropdown-empty:hover {
  background: #fafafa;
}

.filter-buttons-row {
  display: flex;
  margin-top: 22px;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 12px;
}

.filter-action-button {
  display: inline-flex;
  min-width: 125px;
  height: 40px;
  padding: 0 18px;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  border: 1px solid transparent;
  border-radius: 3px;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}

.filter-action-button i {
  margin-right: 7px;
}

.filter-action-button[disabled] {
  cursor: not-allowed;
  opacity: 0.6;
}

.primary-filter-button {
  background: #40ae58;
  border-color: #359a4a;
}

.reset-filter-button {
  color: #444444;
  background: #ffffff;
  border-color: #aaaaaa;
}

.secondary-filter-button {
  background: #687783;
  border-color: #586771;
}

.refresh-filter-button {
  background: #168b99;
  border-color: #117682;
}

.records-loading,
.records-empty-message {
  padding: 45px 20px;
  color: #666666;
  font-size: 15px;
  text-align: center;
}

.records-loading div {
  margin-top: 10px;
}

.records-table-wrapper {
  position: relative;
  z-index: 1;
  width: 100%;
  max-height: 500px;
  overflow-x: auto;
  overflow-y: auto;
  background: #ffffff;
}

.records-table {
  width: 100%;
  min-width: 4250px;
  table-layout: fixed;
  border-collapse: separate;
  border-spacing: 0;
}

.records-table thead th {
  position: sticky;
  z-index: 5;
  top: 0;
  width: 155px;
  min-width: 155px;
  max-width: 155px;
  padding: 10px 12px;
  color: #ffffff;
  background: #959595;
  border-right: 1px solid #b7b7b7;
  border-bottom: 1px solid #777777;
  font-size: 14px;
  font-weight: 700;
  text-align: center;
  vertical-align: middle;
}

.records-table tbody td {
  width: 155px;
  min-width: 155px;
  max-width: 155px;
  padding: 12px 13px;
  color: #4c4c4c;
  background: #ffffff;
  border-right: 1px solid #eeeeee;
  border-bottom: 2px solid #d5e9f4;
  font-size: 13px;
  text-align: center;
  vertical-align: top;
  word-break: break-word;
}

.records-table tbody tr:hover td {
  background: #fafafa;
}

.request-header {
  position: sticky !important;
  z-index: 12 !important;
  left: 0;
  width: 175px !important;
  min-width: 175px !important;
  max-width: 175px !important;
  background: #898989 !important;
}

.request-number-column {
  position: sticky;
  z-index: 6;
  left: 0;
  width: 175px !important;
  min-width: 175px !important;
  max-width: 175px !important;
  background: #ffffff !important;
}

.large-text-header,
.large-text-column {
  width: 280px !important;
  min-width: 280px !important;
  max-width: 280px !important;
}

.large-text-column {
  text-align: left !important;
}

.long-text-value {
  display: -webkit-box;
  overflow: hidden;
  line-height: 18px;
  text-overflow: ellipsis;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 4;
}

.status-header {
  position: sticky !important;
  z-index: 11 !important;
  right: 200px;
  width: 175px !important;
  min-width: 175px !important;
  max-width: 175px !important;
  background: #898989 !important;
}

.status-column {
  position: sticky;
  z-index: 7;
  right: 200px;
  width: 175px !important;
  min-width: 175px !important;
  max-width: 175px !important;
  background: #ffffff !important;
  vertical-align: middle !important;
}

.actions-header {
  position: sticky !important;
  z-index: 12 !important;
  right: 0;
  width: 200px !important;
  min-width: 200px !important;
  max-width: 200px !important;
  background: #818181 !important;
}

.actions-column {
  position: sticky;
  z-index: 8;
  right: 0;
  width: 200px !important;
  min-width: 200px !important;
  max-width: 200px !important;
  background: #ffffff !important;
  vertical-align: middle !important;
}

.status-label {
  display: inline-block;
  min-width: 110px;
  max-width: 155px;
  padding: 6px 10px;
  border-radius: 14px;
  font-size: 11px;
  font-weight: 600;
  text-align: center;
}

.status-draft {
  color: #495057;
  background: #e9ecef;
}

.status-submitted {
  color: #004085;
  background: #cce5ff;
}

.status-approval {
  color: #856404;
  background: #fff3cd;
}

.status-approved {
  color: #155724;
  background: #c3e6cb;
}

.status-progress {
  color: #7a4b00;
  background: #ffe6a1;
}

.status-feedback {
  color: #0c5460;
  background: #d1ecf1;
}

.status-complete {
  color: #155724;
  background: #d4edda;
}

.status-rejected {
  color: #721c24;
  background: #f8d7da;
}

.status-default {
  color: #383d41;
  background: #e2e3e5;
}

.record-actions {
  display: flex;
  min-height: 42px;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 9px;
}

.record-action-button {
  display: inline-flex;
  width: 36px;
  height: 36px;
  padding: 0;
  align-items: center;
  justify-content: center;
  color: #ed6b21;
  background: transparent;
  border: 0;
  border-radius: 3px;
  font-size: 23px;
  cursor: pointer;
}

.record-action-button:hover {
  color: #c94d08;
  background: #fff2ea;
}

.edit-button {
  color: #111111;
  border: 2px solid #111111;
  font-size: 19px;
}

.edit-button:hover {
  color: #ffffff;
  background: #111111;
}

.records-back-section {
  padding: 9px 11px;
  background: #ffffff;
  border-top: 1px solid #eeeeee;
}

.records-back-button {
  display: inline-flex;
  width: 40px;
  height: 40px;
  padding: 0;
  align-items: center;
  justify-content: center;
  color: #111111;
  background: #ffffff;
  border: 3px solid #111111;
  border-radius: 50%;
  font-size: 22px;
  cursor: pointer;
}

.completion-overlay {
  position: fixed;
  z-index: 1050;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 28px 15px;
  overflow-y: auto;
  background: rgba(0, 0, 0, 0.62);
  isolation: isolate;
}

.completion-popup {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 780px;
  margin: 0 auto;
  overflow: hidden;
  background: #ffffff;
  border-radius: 5px;
  box-shadow: 0 12px 45px rgba(0, 0, 0, 0.4);
}

.completion-popup-header {
  display: flex;
  padding: 18px 22px;
  align-items: flex-start;
  justify-content: space-between;
  color: #ffffff;
  background: #ed6b21;
}

.completion-popup-header h4 {
  margin: 0 0 5px;
  font-size: 21px;
  font-weight: 600;
}

.completion-popup-header p {
  margin: 0;
}

.popup-close-button {
  padding: 0;
  color: #ffffff;
  background: transparent;
  border: 0;
  font-size: 31px;
  cursor: pointer;
}

.completion-popup-body {
  max-height: 68vh;
  padding: 22px;
  overflow-y: auto;
}

.completion-popup-body label {
  color: #333333;
  font-weight: 600;
}

.completion-popup-footer {
  position: relative;
  z-index: 5;
  clear: both;
  padding: 15px 22px;
  text-align: right;
  background: #f5f5f5;
  border-top: 1px solid #dddddd;
}

.completion-popup-footer .btn {
  margin-left: 8px;
}

.submit-completion-button {
  color: #ffffff;
  background: #ed6b21;
  border-color: #d65d18;
}

.mandatory {
  color: #d9534f;
}

.certificate-section {
  position: relative;
  z-index: 2;
  padding: 17px;
  margin-top: 18px;
  overflow: visible;
  background: #fafafa;
  border: 1px dashed #999999;
}

.native-attachment-container {
  position: relative;
  z-index: 3;
  display: flex;
  width: 100%;
  min-height: 42px;
  margin-top: 10px;
  align-items: center;
  gap: 10px;
}

.native-attachment-container sp-attachment-button {
  position: relative;
  z-index: 4;
  display: inline-block;
  width: auto;
  max-width: 100%;
}

.native-attachment-container button,
.native-attachment-container .btn {
  float: none !important;
  width: auto;
  max-width: 100%;
  margin: 0 !important;
  transform: none !important;
}

.attach-certificate-label {
  color: #ed6b21;
  font-weight: 600;
}

.certificate-uploading {
  margin-top: 12px;
  color: #337ab7;
}

.uploaded-attachments {
  position: relative;
  z-index: 2;
  width: 100%;
  margin-top: 16px;
  clear: both;
}

.uploaded-attachment-row {
  display: flex;
  width: 100%;
  padding: 10px;
  margin-bottom: 7px;
  align-items: center;
  justify-content: space-between;
  background: #ffffff;
  border: 1px solid #dddddd;
}

.uploaded-attachment-name {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.uploaded-attachment-size {
  margin-left: 8px;
  color: #777777;
  font-size: 12px;
}

.delete-attachment-button {
  color: #d9534f;
  background: transparent;
  border: 0;
  font-size: 17px;
}

.no-certificate-message {
  margin-top: 12px;
  color: #777777;
}

@media screen and (max-width: 1000px) {
  .records-page-header {
    flex-wrap: wrap;
  }

  .filter-fields-container {
    grid-template-columns: 1fr;
  }
}

@media screen and (max-width: 650px) {
  .filter-item {
    display: block;
  }

  .filter-item label {
    display: block;
    width: auto;
    margin-bottom: 5px;
    text-align: left;
  }

  .filter-buttons-row {
    flex-direction: column;
  }

  .filter-action-button {
    width: 100%;
  }

  .completion-overlay {
    padding: 8px;
  }

  .completion-popup-footer .btn {
    display: block;
    width: 100%;
    margin: 6px 0;
  }
}

sp_widget.script:
(function() {
  var TABLE =
    "x_1549902_asean_0_learning_application";

  var STATUS_FIELD = "u_status";

  var STATUS_DRAFT = "draft";
  var STATUS_LEARNING =
    "learning_in_progress";
  var STATUS_FEEDBACK =
    "pending_feedback";

  data.records = [];
  data.attachments = [];
  data.success = true;
  data.message = "";

  data.userEmail =
    gs.getUser().getEmail() || "";

  data.userName =
    gs.getUserDisplayName();

  data.userLevel = "Employee";
  data.tableName = TABLE;

  data.filterOptions = {
    requestNumbers: [],
    courseTypes: [],
    courseFormats: [],
    statuses: []
  };

  function getValue(gr, fieldName) {
    if (
      !gr ||
      !gr.isValidField(fieldName)
    ) {
      return "";
    }

    return gr.getValue(fieldName) || "";
  }

  function getDisplay(gr, fieldName) {
    if (
      !gr ||
      !gr.isValidField(fieldName)
    ) {
      return "";
    }

    return gr.getDisplayValue(fieldName) || "";
  }

  function addUnique(array, value) {
    if (
      value &&
      array.indexOf(value) === -1
    ) {
      array.push(value);
    }
  }

  function addUniqueObject(
    array,
    value,
    displayValue
  ) {
    if (!value) {
      return;
    }

    for (var i = 0; i < array.length; i++) {
      if (array[i].value === value) {
        return;
      }
    }

    array.push({
      value: value,
      display: displayValue || value
    });
  }

  function addEmployeeQuery(gr) {
    var employeeQuery = gr.addQuery(
      "u_employee_name",
      gs.getUserID()
    );

    if (data.userEmail) {
      employeeQuery.addOrCondition(
        "u_employee_email",
        data.userEmail
      );
    }
  }

  function getEmployeeRecord(sysId) {
    if (!sysId) {
      return null;
    }

    var gr =
      new GlideRecordSecure(TABLE);

    gr.addQuery("sys_id", sysId);
    addEmployeeQuery(gr);
    gr.setLimit(1);
    gr.query();

    if (gr.next()) {
      return gr;
    }

    return null;
  }

  function loadFilterOptions() {
    data.filterOptions = {
      requestNumbers: [],
      courseTypes: [],
      courseFormats: [],
      statuses: []
    };

    var gr =
      new GlideRecordSecure(TABLE);

    addEmployeeQuery(gr);
    gr.orderByDesc("sys_created_on");
    gr.query();

    while (gr.next()) {
      addUnique(
        data.filterOptions.requestNumbers,
        getDisplay(gr, "number")
      );

      addUniqueObject(
        data.filterOptions.courseTypes,
        getValue(gr, "u_course_type"),
        getDisplay(gr, "u_course_type")
      );

      addUniqueObject(
        data.filterOptions.courseFormats,
        getValue(gr, "u_course_format"),
        getDisplay(gr, "u_course_format")
      );

      addUniqueObject(
        data.filterOptions.statuses,
        getValue(gr, STATUS_FIELD),
        getDisplay(gr, STATUS_FIELD)
      );
    }

    data.filterOptions.requestNumbers.sort();
  }

  function loadRecords(filters) {
    filters = filters || {};

    var records = [];
    var gr =
      new GlideRecordSecure(TABLE);

    addEmployeeQuery(gr);

    /*
     * Free-text request number search.
     *
     * LEA0001039 finds exact record.
     * 1039 also finds LEA0001039.
     */
    if (filters.requestNumber) {
      var requestNumber =
        String(filters.requestNumber).trim();

      if (requestNumber) {
        gr.addQuery(
          "number",
          "CONTAINS",
          requestNumber
        );
      }
    }

    if (filters.courseType) {
      gr.addQuery(
        "u_course_type",
        filters.courseType
      );
    }

    if (filters.courseFormat) {
      gr.addQuery(
        "u_course_format",
        filters.courseFormat
      );
    }

    if (filters.status) {
      gr.addQuery(
        STATUS_FIELD,
        filters.status
      );
    }

    gr.orderByDesc("sys_created_on");
    gr.query();

    while (gr.next()) {
      var statusValue =
        getValue(gr, STATUS_FIELD);

      records.push({
        sys_id:
          gr.getUniqueValue(),

        requestNumber:
          getDisplay(gr, "number"),

        employeeName:
          getDisplay(
            gr,
            "u_employee_name"
          ),

        employeeEmail:
          getValue(
            gr,
            "u_employee_email"
          ),

        country:
          getDisplay(
            gr,
            "u_country"
          ),

        manager:
          getDisplay(
            gr,
            "u_manager_email"
          ),

        managementL2:
          getDisplay(
            gr,
            "u_management_l2"
          ),

        managerL2Required:
          getDisplay(
            gr,
            "manager_approval_l2_required"
          ),

        courseTitle:
          getDisplay(
            gr,
            "u_course_title"
          ),

        courseType:
          getDisplay(
            gr,
            "u_course_type"
          ),

        courseFormat:
          getDisplay(
            gr,
            "u_course_format"
          ),

        courseStartDate:
          getDisplay(
            gr,
            "course_start_date"
          ),

        courseEndDate:
          getDisplay(
            gr,
            "u_course_end_date"
          ),

        totalTrainingHours:
          getDisplay(
            gr,
            "u_total_training_hours"
          ),

        trainingCountry:
          getDisplay(
            gr,
            "u_training_country"
          ),

        trainingProvider:
          getDisplay(
            gr,
            "u_training_provider_name"
          ),

        paymentRequired:
          getDisplay(
            gr,
            "is_payment_required"
          ),

        courseFee:
          getDisplay(
            gr,
            "u_course_fee"
          ),

        otherExpenses:
          getDisplay(
            gr,
            "u_other_expenses"
          ),

        specifyOtherExpenses:
          getDisplay(
            gr,
            "u_specify_other_expenses"
          ),

        totalCost:
          getDisplay(
            gr,
            "u_total_cost"
          ),

        currency:
          getDisplay(
            gr,
            "currency"
          ),

        comment:
          getValue(
            gr,
            "u_comment"
          ),

        approval:
          getDisplay(
            gr,
            "approval"
          ),

        openedAt:
          getDisplay(
            gr,
            "opened_at"
          ),

        status:
          getDisplay(
            gr,
            STATUS_FIELD
          ),

        statusValue:
          statusValue,

        canEdit:
          statusValue === STATUS_DRAFT,

        canUploadCertificate:
          statusValue === STATUS_LEARNING,

        canProvideFeedback:
          statusValue === STATUS_FEEDBACK
      });
    }

    return records;
  }

  function loadAttachments(parentSysId) {
    data.attachments = [];

    var attachmentGr =
      new GlideRecordSecure(
        "sys_attachment"
      );

    attachmentGr.addQuery(
      "table_name",
      TABLE
    );

    attachmentGr.addQuery(
      "table_sys_id",
      parentSysId
    );

    attachmentGr.orderByDesc(
      "sys_created_on"
    );

    attachmentGr.query();

    while (attachmentGr.next()) {
      var sizeBytes = parseInt(
        attachmentGr.getValue(
          "size_bytes"
        ),
        10
      ) || 0;

      var sizeDisplay = "";

      if (
        sizeBytes >=
        1024 * 1024
      ) {
        sizeDisplay =
          (
            sizeBytes /
            (1024 * 1024)
          ).toFixed(2) +
          " MB";
      } else {
        sizeDisplay =
          (
            sizeBytes /
            1024
          ).toFixed(2) +
          " KB";
      }

      data.attachments.push({
        sys_id:
          attachmentGr.getUniqueValue(),

        file_name:
          attachmentGr.getValue(
            "file_name"
          ),

        content_type:
          attachmentGr.getValue(
            "content_type"
          ),

        size_bytes:
          sizeBytes,

        size:
          sizeDisplay
      });
    }
  }

  function hasCertificate(parentSysId) {
    var attachmentGr =
      new GlideRecordSecure(
        "sys_attachment"
      );

    attachmentGr.addQuery(
      "table_name",
      TABLE
    );

    attachmentGr.addQuery(
      "table_sys_id",
      parentSysId
    );

    attachmentGr.setLimit(1);
    attachmentGr.query();

    return attachmentGr.hasNext();
  }

  function getCertificateNames(
    parentSysId
  ) {
    var fileNames = [];

    var attachmentGr =
      new GlideRecordSecure(
        "sys_attachment"
      );

    attachmentGr.addQuery(
      "table_name",
      TABLE
    );

    attachmentGr.addQuery(
      "table_sys_id",
      parentSysId
    );

    attachmentGr.orderByDesc(
      "sys_created_on"
    );

    attachmentGr.query();

    while (attachmentGr.next()) {
      fileNames.push(
        attachmentGr.getValue(
          "file_name"
        ) || "Attachment"
      );
    }

    return fileNames;
  }

  /*
   * Load certificate attachments.
   */
  if (
    input &&
    input.action === "get_attachments"
  ) {
    var attachmentParent =
      getEmployeeRecord(input.sys_id);

    if (!attachmentParent) {
      data.success = false;
      data.message =
        "Learning application not found " +
        "or access denied.";
      return;
    }

    loadAttachments(
      attachmentParent.getUniqueValue()
    );

    data.success = true;
    return;
  }

  /*
   * Submit certificate and move to
   * Pending Feedback.
   */
  if (
    input &&
    input.action ===
      "submit_for_feedback"
  ) {
    var updateGr =
      getEmployeeRecord(input.sys_id);

    if (!updateGr) {
      data.success = false;
      data.message =
        "Learning application not found " +
        "or access denied.";
      return;
    }

    var currentStatus =
      getValue(
        updateGr,
        STATUS_FIELD
      );

    if (
      currentStatus !==
      STATUS_LEARNING
    ) {
      data.success = false;
      data.message =
        "Only Learning In Progress " +
        "applications can submit a " +
        "completion certificate.";
      return;
    }

    if (
      !hasCertificate(
        updateGr.getUniqueValue()
      )
    ) {
      data.success = false;
      data.message =
        "Please upload the completion " +
        "certificate before submitting.";
      return;
    }

    var form = input.form || {};
    var completionComment = "";

    if (
      form.completionComment !==
        undefined &&
      form.completionComment !== null
    ) {
      completionComment =
        String(
          form.completionComment
        ).trim();
    }

    if (!completionComment) {
      data.success = false;
      data.message =
        "Completion Comments are mandatory.";
      return;
    }

    var certificateNames =
      getCertificateNames(
        updateGr.getUniqueValue()
      );

    if (
      updateGr.isValidField(
        "u_comment"
      )
    ) {
      updateGr.setValue(
        "u_comment",
        completionComment
      );
    }

    if (
      updateGr.isValidField(
        "work_notes"
      )
    ) {
      var workNoteLines = [];

      workNoteLines.push(
        "Completion certificate uploaded by employee."
      );

      workNoteLines.push(
        "Request Number: " +
        getDisplay(
          updateGr,
          "number"
        )
      );

      workNoteLines.push(
        "Employee: " +
        gs.getUserDisplayName()
      );

      workNoteLines.push(
        "Course Title: " +
        getDisplay(
          updateGr,
          "u_course_title"
        )
      );

      workNoteLines.push(
        "Certificate File(s): " +
        (
          certificateNames.length > 0
            ? certificateNames.join(", ")
            : "Certificate uploaded"
        )
      );

      workNoteLines.push(
        "Completion Comments: " +
        completionComment
      );

      workNoteLines.push(
        "Status changed from Learning In Progress " +
        "to Pending Feedback."
      );

      updateGr.work_notes =
        workNoteLines.join("\n");
    }

    updateGr.setValue(
      STATUS_FIELD,
      STATUS_FEEDBACK
    );

    var updatedSysId =
      updateGr.update();

    if (!updatedSysId) {
      data.success = false;
      data.message =
        "The learning application " +
        "could not be updated.";
      return;
    }

    data.success = true;

    data.message =
      "Certificate and completion comments " +
      "submitted successfully. The request " +
      "has moved to Pending Feedback.";

    loadFilterOptions();

    data.records = loadRecords(
      input.filters || {}
    );

    return;
  }

  /*
   * Search records.
   */
  if (
    input &&
    input.action === "search"
  ) {
    data.records = loadRecords(
      input.filters || {}
    );

    data.success = true;
    return;
  }

  /*
   * Refresh records and dropdown options.
   */
  if (
    input &&
    input.action === "refresh"
  ) {
    loadFilterOptions();

    data.records = loadRecords(
      input.filters || {}
    );

    data.success = true;
    return;
  }

  /*
   * Reset.
   */
  if (
    input &&
    input.action === "reset"
  ) {
    loadFilterOptions();

    data.records = loadRecords({});

    data.success = true;
    return;
  }

  /*
   * Initial widget load.
   */
  loadFilterOptions();
  data.records = loadRecords({});
})();
